    schema_: Annotated[
        SchemaById | SchemaInlineInput | SchemaFields | None,
        Field(alias="schema", title="Schema"),
    ] = None
    strategy: Annotated[Strategy2 | None, Field(title="Strategy")] = "bfs"
    url: Annotated[str, Field(title="Url")]
